    sizeClass: def.sizeClass || 'M',
    massKg: def.massKg ?? 60,
    resistances,
    speed: def.speed ?? 1,
    description: def.description || def.name,
  };

  // Optional AI fields
  if (def.visionRange != null) monsterDef.visionRange = def.visionRange;
  if (def.aggro) monsterDef.aggro = def.aggro;
  if (def.alertOnSight != null) monsterDef.alertOnSight = def.alertOnSight === true;
  if (def.sightAlertCooldownTurns != null) monsterDef.sightAlertCooldownTurns = Math.max(0, Number(def.sightAlertCooldownTurns || 0) | 0);
  if (def.faction) monsterDef.faction = def.faction;
  if (def.solid != null) monsterDef.solid = def.solid === true;
  if (def.blocksSight != null) monsterDef.blocksSight = def.blocksSight === true;
  if (def.packSense != null) monsterDef.packSense = def.packSense;
  if (def.packRadius != null) monsterDef.packRadius = def.packRadius;
  if (def.retreatHpPct != null) monsterDef.retreatHpPct = def.retreatHpPct;
  if (def.ambush != null) monsterDef.ambush = def.ambush;
  if (def.polymorphResistance != null) monsterDef.polymorphResistance = clamp(Number(def.polymorphResistance || 0), 0, 1);
  if (def.polymorphStability != null) monsterDef.polymorphStability = normalizePolymorphStability(def.polymorphStability);
  if (typeof def.sleep === 'string') {
    monsterDef.sleep = def.sleep;
  } else if (def.sleep && typeof def.sleep === 'object') {
    monsterDef.sleep = { ...def.sleep };
  }

  // Equipment
  if (def.wielding) monsterDef.wielding = def.wielding;
  if (def.equipped) monsterDef.equipped = def.equipped;
  if (def.inventory) monsterDef.inventory = def.inventory;

  // Spells
  if (def.learnedSpellIds) monsterDef.learnedSpellIds = def.learnedSpellIds;
  if (def.maxMana != null) monsterDef.maxMana = def.maxMana;
  if (def.manaRegen != null) monsterDef.manaRegen = def.manaRegen;

  // Loot
  if (def.lootTable) monsterDef.lootTable = def.lootTable;
  if (def.corpseDropChance != null) monsterDef.corpseDropChance = def.corpseDropChance;
  if (def.goreType) monsterDef.goreType = def.goreType;

  // ── Hooks ──────────────────────────────────────────────────────
  // Merge raw callback arrays (existing pattern) with compiled DSL hooks.
  const hooks = def.hooks ? { ...def.hooks } : {};
  _compileMonsterDslHooks(id, def, hooks);
  if (Object.keys(hooks).length > 0) monsterDef.hooks = hooks;

  // Special descriptions (for bestiary / tooltip)
  if (def.specials) monsterDef.specials = def.specials;

  // Flags
  if (def.canFly) monsterDef.canFly = def.canFly;
  if (def.rare) monsterDef.rare = def.rare;
  if (def.disabled) monsterDef.disabled = def.disabled;
  if (def.minDepth != null) monsterDef.minDepth = def.minDepth;
  if (def.equipment) monsterDef.equipment = def.equipment;
  if (def.guardianRole && typeof def.guardianRole === "object") {
    monsterDef.guardianRole = { ...def.guardianRole };
  }

  // Corpse eating
  if (def.corpseEat) monsterDef.corpseEat = def.corpseEat;

  // Local persistent state
  if (def.state && typeof def.state === 'object') {
    monsterDef._contentState = { ...def.state };
  }

  // AI hints
  if (def.aiHints) monsterDef._contentAiHints = def.aiHints;

  // Metadata
  if (def.meta) monsterDef._contentMeta = def.meta;

  // ── Register ──────────────────────────────────────────────────
  registerMonster(id, monsterDef);
  registerMonsterDef(monsterDef);  // eager: available via getMonster() immediately

  // ── Palette ───────────────────────────────────────────────────
  if (def.glyph || def.color) {
    const entry = {};
    if (def.glyph) entry.glyph = def.glyph;
    if (def.color) entry.fg = def.color;
    entry.glow = def.glow || def.color || null;
    if (def.scale != null) entry.baseScale = Number(def.scale);
    registerPalette(id, entry);
  }

  // ── Presentations ─────────────────────────────────────────────
  if (def.presentations && typeof def.presentations === 'object') {
    for (const [presId, spec] of Object.entries(def.presentations)) {
      registerPresentation(id, presId, spec);
    }
  }

  return id;
}

// src/content/registry.js
// Central content registry. All defineItem() / defineMonster() /
// defineInteractable() calls
// register their compiled outputs here. installContent() reads from here
// and wires everything into the existing engine registries.

/** @type {Map<string, object>} id → compiled catalog-compatible item def */
const _items = new Map();

/** @type {Map<string, object>} id → compiled MonsterDef-compatible object */
const _monsters = new Map();

/** @type {Map<string, object>} action → compiled interaction definition */
const _interactables = new Map();

/** @type {Map<string, { glyph: string, fg: string, glow?: string, baseScale?: number }>} */
const _palettes = new Map();

// ── Items ──────────────────────────────────────────────────────────

export function registerItem(id, compiledDef) {
  if (_items.has(id)) {
    throw new Error(`[content] Duplicate item definition: "${id}"`);
  }
  _items.set(id, compiledDef);
}

export function getContentItem(id) { return _items.get(id) || null; }
export function allContentItems() { return _items; }

// ── Monsters ───────────────────────────────────────────────────────

export function registerMonster(id, compiledDef) {
  if (_monsters.has(id)) {
    throw new Error(`[content] Duplicate monster definition: "${id}"`);
  }
  _monsters.set(id, compiledDef);
}

export function getContentMonster(id) { return _monsters.get(id) || null; }
export function allContentMonsters() { return _monsters; }

// ── Interactables ───────────────────────────────────────────────────

export function registerInteractable(action, compiledDef) {
  if (_interactables.has(action)) {
    throw new Error(`[content] Duplicate interactable definition: "${action}"`);
  }
  _interactables.set(action, compiledDef);
}

export function allContentInteractables() { return _interactables; }

// ── Palette ────────────────────────────────────────────────────────

export function registerPalette(identity, entry) {
  _palettes.set(identity, entry);
}

export function allContentPalettes() { return _palettes; }

// ── Presentations ──────────────────────────────────────────────────

/** @type {Map<string, Map<string, object>>} identity → presentationId → spec */
const _presentations = new Map();

export function registerPresentation(identity, presentationId, spec) {
  if (!_presentations.has(identity)) _presentations.set(identity, new Map());
  _presentations.get(identity).set(presentationId, spec);
}

/**
 * Look up a presentation spec.
 * @param {string} identity - thing identity (e.g. "sun_vessel")
 * @param {string} presentationId - event name (e.g. "sun_vessel_pulse")
 * @returns {object|null}
 */
export function getPresentation(identity, presentationId) {
  return _presentations.get(identity)?.get(presentationId) || null;
}

export function allContentPresentations() { return _presentations; }

// ── Abilities ──────────────────────────────────────────────────────

/** @type {Map<string, Map<string, object>>} itemIdentity → abilityId → ability spec */
const _abilities = new Map();

export function registerAbility(identity, abilityId, spec) {
  if (!_abilities.has(identity)) _abilities.set(identity, new Map());
  _abilities.get(identity).set(abilityId, spec);
}

/**
 * Get all abilities for an item identity.
 * @param {string} identity
 * @returns {Map<string, object>|null}
 */
export function getAbilities(identity) {
  return _abilities.get(identity) || null;
}

/**
 * Get a single ability spec.
 * @param {string} identity
 * @param {string} abilityId
 * @returns {object|null}
 */
export function getAbility(identity, abilityId) {
  return _abilities.get(identity)?.get(abilityId) || null;
}

export function allContentAbilities() { return _abilities; }

// ── Testing ────────────────────────────────────────────────────────

/** Reset all registries. Test-only. */
export function clearContentRegistry() {
  _items.clear();
  _monsters.clear();
  _interactables.clear();
  _palettes.clear();
  _presentations.clear();
  _abilities.clear();
}
