 * @param {object} [def.meta]
 *
 * @returns {string} The registered monster id
 */
export function defineMonster(id, def) {
  if (!id || typeof id !== 'string') throw new Error('[defineMonster] id is required');
  if (!def || typeof def !== 'object') throw new Error('[defineMonster] def is required');
  if (!def.name) throw new Error(`[defineMonster "${id}"] name is required`);

  const resistances = _buildResistances(def);

  const monsterDef = {
    id,
    name: def.name,
    tags: def.tags || [],
    tier: def.tier ?? 0,
    intelligence: def.intelligence ?? 3,
    baseHp: def.hp ?? 10,
    hpPerLevel: def.hpPerLevel ?? 1,
    attack: def.attack ?? 1,
    defense: def.defense ?? 0,
    damageDice: def.damageDice || '1d4',
    sizeClass: def.sizeClass || 'M',
    massKg: def.massKg ?? 60,
    resistances,
    speed: def.speed ?? 1,
    description: def.description || def.name,
  };

  // Optional AI fields
  if (def.visionRange != null) monsterDef.visionRange = def.visionRange;
  if (def.aggro) monsterDef.aggro = def.aggro;
  if (def.alertOnSight != null) monsterDef.alertOnSight = def.alertOnSight === true;
  if (def.sightAlertCooldownTurns != null) monsterDef.sightAlertCooldownTurns = Math.max(0, Number(def.sightAlertCooldownTurns || 0) | 0);
  if (def.faction) monsterDef.faction = def.faction;
  if (def.solid != null) monsterDef.solid = def.solid === true;
  if (def.blocksSight != null) monsterDef.blocksSight = def.blocksSight === true;
  if (def.packSense != null) monsterDef.packSense = def.packSense;
  if (def.packRadius != null) monsterDef.packRadius = def.packRadius;
  if (def.retreatHpPct != null) monsterDef.retreatHpPct = def.retreatHpPct;
  if (def.ambush != null) monsterDef.ambush = def.ambush;
  if (def.polymorphResistance != null) monsterDef.polymorphResistance = clamp(Number(def.polymorphResistance || 0), 0, 1);
  if (def.polymorphStability != null) monsterDef.polymorphStability = normalizePolymorphStability(def.polymorphStability);
  if (typeof def.sleep === 'string') {
    monsterDef.sleep = def.sleep;
  } else if (def.sleep && typeof def.sleep === 'object') {
    monsterDef.sleep = { ...def.sleep };
  }

  // Equipment
  if (def.wielding) monsterDef.wielding = def.wielding;
  if (def.equipped) monsterDef.equipped = def.equipped;
  if (def.inventory) monsterDef.inventory = def.inventory;

  // Spells
  if (def.learnedSpellIds) monsterDef.learnedSpellIds = def.learnedSpellIds;
  if (def.maxMana != null) monsterDef.maxMana = def.maxMana;
  if (def.manaRegen != null) monsterDef.manaRegen = def.manaRegen;

  // Loot
  if (def.lootTable) monsterDef.lootTable = def.lootTable;
  if (def.corpseDropChance != null) monsterDef.corpseDropChance = def.corpseDropChance;
  if (def.goreType) monsterDef.goreType = def.goreType;

  // ── Hooks ──────────────────────────────────────────────────────
  // Merge raw callback arrays (existing pattern) with compiled DSL hooks.
  const hooks = def.hooks ? { ...def.hooks } : {};
  _compileMonsterDslHooks(id, def, hooks);
  if (Object.keys(hooks).length > 0) monsterDef.hooks = hooks;

  // Special descriptions (for bestiary / tooltip)
  if (def.specials) monsterDef.specials = def.specials;

  // Flags
  if (def.canFly) monsterDef.canFly = def.canFly;
  if (def.rare) monsterDef.rare = def.rare;
  if (def.disabled) monsterDef.disabled = def.disabled;
  if (def.minDepth != null) monsterDef.minDepth = def.minDepth;
  if (def.equipment) monsterDef.equipment = def.equipment;
  if (def.guardianRole && typeof def.guardianRole === "object") {
    monsterDef.guardianRole = { ...def.guardianRole };
  }

  // Corpse eating
  if (def.corpseEat) monsterDef.corpseEat = def.corpseEat;

  // Local persistent state
  if (def.state && typeof def.state === 'object') {
    monsterDef._contentState = { ...def.state };
  }

  // AI hints
  if (def.aiHints) monsterDef._contentAiHints = def.aiHints;

  // Metadata
  if (def.meta) monsterDef._contentMeta = def.meta;

  // ── Register ──────────────────────────────────────────────────
  registerMonster(id, monsterDef);
  registerMonsterDef(monsterDef);  // eager: available via getMonster() immediately

import { Equipment, NON_AMMO_GEAR_SLOTS } from "../components/Equipment.js";
import { ItemInfo } from "../components/ItemInfo.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { PolymorphExposure } from "../components/PolymorphExposure.js";
import {
  PolymorphProfile,
  POLYMORPH_STABILITY,
  polymorphStabilityScore,
  normalizePolymorphStability,
} from "../components/PolymorphProfile.js";
import { Traits } from "../components/Traits.js";
import { getAllMonsters, getMonster } from "../data/monsters.js";
import { clamp01 } from "./numberCoerce.js";
import { getPassiveBonuses } from "./passiveBonuses.js";

function addSource(sources, source) {
  const key = String(source || "");
  if (key && !sources.includes(key)) sources.push(key);
}

function collectEquipmentControlSources(world, actorId, sources) {
  const eq = world.get(actorId, Equipment);
  if (!eq) return;
  for (const slot of NON_AMMO_GEAR_SLOTS) {
    const itemId = Number(eq[slot] || 0) | 0;
    if (!(itemId > 0) || !world.isAlive?.(itemId)) continue;
    const info = world.get(itemId, ItemInfo);
    const amount = Number(info?.bonuses?.polymorphControl || 0);
    if (!(amount > 0)) continue;
    const ident = world.get(itemId, NamedIdentity);
    addSource(sources, String(ident?.identity || ident?.name || `item:${itemId}`));
  }
}

/**
 * Resolve the actor's polymorph-control capability from permanent traits and
 * derived passive bonuses. Future surfaces should extend this function, not
 * scroll or UI code.
 *
 * @param {any} world
 * @param {number} actorId
 * @returns {{ hasControl:boolean, controlScore:number, powerScore:number, sources:string[] }}
 */
export function getPolymorphControl(world, actorId) {
  const id = Number(actorId || 0) | 0;
  const sources = [];
  if (!(id > 0) || !world?.isAlive?.(id)) {
    return Object.freeze({ hasControl: false, controlScore: 0, powerScore: 0, sources });
  }

  const traits = world.get(id, Traits);
  let controlScore = traits?.polymorph_control ? 1 : 0;
  if (traits?.polymorph_control) addSource(sources, "trait:polymorph_control");

  const passive = getPassiveBonuses(world, id);
  const passiveControl = Number(passive?.polymorphControlDerived || 0);
  const powerScore = Number(passive?.polymorphPowerDerived || 0);
  if (passiveControl > 0) {
    controlScore += passiveControl;
    collectEquipmentControlSources(world, id, sources);
    if (!sources.some((source) => source.startsWith("ring_") || source.startsWith("item:"))) {
      addSource(sources, "passive:polymorph_control");
    }
  }

  return Object.freeze({
    hasControl: controlScore > 0,
    controlScore,
    powerScore,
    sources: Object.freeze(sources),
  });
}

/**
 * Resolve a target's resistance to being polymorphed. Runtime components are
 * checked first so non-monster entities can opt into policy without pretending
 * to be content monsters. Monster authoring data is the fallback for ordinary
 * creatures.
 *
 * @param {any} world
 * @param {number} targetId
 * @returns {{ resistanceScore:number, stability:string, stabilityScore:number, exposureBonus:number, sources:string[] }}
 */
export function getPolymorphResistance(world, targetId) {
  const id = Number(targetId || 0) | 0;
  const sources = [];
  if (!(id > 0) || !world?.isAlive?.(id)) {
    return Object.freeze({
      resistanceScore: 0,
      stability: POLYMORPH_STABILITY.ordinary,
      stabilityScore: polymorphStabilityScore(POLYMORPH_STABILITY.ordinary),
      exposureBonus: 0,
      sources,
    });
  }

  let resistanceScore = 0;
  let stability = POLYMORPH_STABILITY.ordinary;

  const profile = world.get(id, PolymorphProfile);
  if (profile) {
    resistanceScore = clamp01(profile.resistance);
    stability = normalizePolymorphStability(profile.stability);
    if (resistanceScore > 0 || stability !== POLYMORPH_STABILITY.ordinary) addSource(sources, "component:polymorph_profile");
  } else {
    const identity = String(world.get(id, NamedIdentity)?.identity || "");
    const def = identity ? getMonster(identity) : null;
    resistanceScore = clamp01(def?.polymorphResistance || 0);
    stability = normalizePolymorphStability(def?.polymorphStability);
    if (resistanceScore > 0 || stability !== POLYMORPH_STABILITY.ordinary) addSource(sources, `monster:${identity}`);
  }

  const passive = getPassiveBonuses(world, id);
  const passiveResistance = Number(passive?.polymorphResistanceDerived || 0);
  const passiveStability = Number(passive?.polymorphStabilityDerived || 0);
  if (passiveResistance > 0) {
    resistanceScore += passiveResistance;
    addSource(sources, "passive:polymorph_resistance");
  }
  if (passiveStability > 0) {
    const boostedScore = polymorphStabilityScore(stability) + passiveStability;
    stability = normalizePolymorphStability(boostedScore);
    addSource(sources, "passive:polymorph_stability");
  }

  const exposure = world.get(id, PolymorphExposure);
  const exposureBonus = clamp01(exposure?.resistanceBonus || 0);
  if (exposureBonus > 0) {
    resistanceScore += exposureBonus;
