    rec.status = String(rec.status || ENCOUNTER_STATES.active);
    rec.activeEntityId = Math.max(0, Number(rec.activeEntityId || 0) | 0);
    rec.activationStep = Number.isFinite(rec.activationStep) ? (rec.activationStep | 0) : 0;
